#### Phase 4: CDN Infrastructure (Week 4)

1. **Provision S3 Bucket**
   ```terraform
   # infrastructure/s3.tf
   resource "aws_s3_bucket" "app_bucket" {
     bucket = "gainwell-enterprise-app"

     tags = {
       Name        = "Enterprise App"
       Environment = "Production"
       Application = "Enterprise™"
     }
   }

   resource "aws_s3_bucket_public_access_block" "app_bucket" {
     bucket = aws_s3_bucket.app_bucket.id

     block_public_acls       = true
     block_public_policy     = true
     ignore_public_acls      = true
     restrict_public_buckets = true
   }
   ```

2. **Configure CloudFront Distribution**
   ```terraform
   # infrastructure/cloudfront.tf
   resource "aws_cloudfront_distribution" "app_distribution" {
     origin {
       domain_name = aws_s3_bucket.app_bucket.bucket_regional_domain_name
       origin_id   = "S3-${aws_s3_bucket.app_bucket.id}"

       s3_origin_config {
         origin_access_identity = aws_cloudfront_origin_access_identity.app.cloudfront_access_identity_path
       }
     }

     enabled             = true
     is_ipv6_enabled     = true
     default_root_object = "index.html"

     default_cache_behavior {
       allowed_methods  = ["GET", "HEAD", "OPTIONS"]
       cached_methods   = ["GET", "HEAD"]
       target_origin_id = "S3-${aws_s3_bucket.app_bucket.id}"

       forwarded_values {
         query_string = false
         cookies {
           forward = "none"
         }
       }

       viewer_protocol_policy = "redirect-to-https"
       min_ttl                = 0
       default_ttl            = 86400  # 24 hours
       max_ttl                = 31536000  # 1 year
       compress               = true
     }

     restrictions {
       geo_restriction {
         restriction_type = "whitelist"
         locations        = ["US"]  # HIPAA compliance
       }
     }

     viewer_certificate {
       acm_certificate_arn      = aws_acm_certificate.app.arn
       ssl_support_method       = "sni-only"
       minimum_protocol_version = "TLSv1.2_2021"
     }
   }
   ```

